63	@RestController
64	@CrossOrigin(exposedHeaders = "errors, content-type")
65	@RequestMapping("/api")
66	public class OwnerRestControllerV1 implements OwnersApi {
67	
68	    /**
69	     * Syntactic check for an email address: a non-empty local part, an {@code @}, and a domain with
70	     * at least one dot and no whitespace on either side.
71	     */
72	    private static final Pattern EMAIL_PATTERN =
73	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
74	
75	    /**
76	     * Common street-type abbreviations expanded during address normalization. Keys are the
77	     * upper-cased abbreviation as it appears as a whole whitespace-delimited token; values are the
78	     * expanded form.
79	     */
80	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
81	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
82	
83	    /**
84	     * The maximum number of owners a single city may contain. A create request for a city that
85	     * already holds this many owners is rejected with a 409 response.
86	     */
87	    private static final int MAX_OWNERS_PER_CITY = 50;
88	
89	    private final ClinicService clinicService;
90	
91	    private final OwnerMapper ownerMapper;
92	
93	    private final PetMapper petMapper;
94	
95	    private final VisitMapper visitMapper;
96	
97	    public OwnerRestControllerV1(ClinicService clinicService,
98	                                 OwnerMapper ownerMapper,
99	                                 PetMapper petMapper,
100	                                 VisitMapper visitMapper) {
101	        this.clinicService = clinicService;
102	        this.ownerMapper = ownerMapper;
103	        this.petMapper = petMapper;
104	        this.visitMapper = visitMapper;
105	    }
106	
107	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
108	    @Override
109	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
110	        Collection<Owner> owners;
111	        if (lastName != null) {
112	            owners = this.clinicService.findOwnerByLastName(lastName);
113	        } else {
114	            owners = this.clinicService.findAllOwners();
115	        }
116	        if (owners.isEmpty()) {
117	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
118	        }
119	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
120	    }
121	
122	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
123	    @Override
124	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
125	        Owner owner = this.clinicService.findOwnerById(ownerId);
126	        if (owner == null) {
127	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
128	        }
129	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
130	    }
131	
132	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
133	    @Override
134	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
135	        normalizeAddress(ownerFieldsDto);
136	        validateRequiredFields(ownerFieldsDto);
137	        normalizeTelephone(ownerFieldsDto);
138	        rejectDuplicateTelephone(ownerFieldsDto);
139	        rejectDuplicateHousehold(ownerFieldsDto);
140	        rejectCityAtCapacity(ownerFieldsDto);
141	        normalizeEmail(ownerFieldsDto);
142	        defaultRegistrationDate(ownerFieldsDto);
143	        HttpHeaders headers = new HttpHeaders();
144	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
145	        assignCustomerCode(owner);
146	        assignMembershipNumber(owner);
147	        assignNamesakeCount(owner);
148	        assignHousehold(owner, ownerFieldsDto);
149	        this.clinicService.saveOwner(owner);
150	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
151	        headers.setLocation(UriComponentsBuilder.newInstance()
152	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
153	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
154	    }
155	
156	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
157	    @Override
158	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
159	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
160	        if (currentOwner == null) {
161	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
162	        }
163	        currentOwner.setAddress(ownerFieldsDto.getAddress());
164	        currentOwner.setCity(ownerFieldsDto.getCity());
165	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
166	        currentOwner.setLastName(ownerFieldsDto.getLastName());
167	        currentOwner.setTelephone(toE164(ownerFieldsDto.getTelephone()));
168	        normalizeEmail(ownerFieldsDto);
169	        currentOwner.setEmail(ownerFieldsDto.getEmail());
170	        this.clinicService.saveOwner(currentOwner);
171	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
172	    }
173	
174	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
175	    @Transactional
176	    @Override
177	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
178	        Owner owner = this.clinicService.findOwnerById(ownerId);
179	        if (owner == null) {
180	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
181	        }
182	        this.clinicService.deleteOwner(owner);
183	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
184	    }
