205	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
206	    @Override
207	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
208	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
209	        if (currentOwner != null) {
210	            Pet currentPet = this.clinicService.findPetById(petId);
211	            if (currentPet != null) {
212	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
213	                currentPet.setName(petFieldsDto.getName());
214	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
215	                this.clinicService.savePet(currentPet);
216	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
217	            }
218	        }
219	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
220	    }
