238	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
239	    @Override
240	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
241	        Owner owner = this.clinicService.findOwnerById(ownerId);
242	        if (owner != null) {
243	            Pet pet = owner.getPet(petId);
244	            if (pet != null) {
245	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
246	            }
247	        }
248	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
249	    }
250	
251	    /**
252	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
253	     * {@code telephone} is missing or blank (including whitespace-only values that Bean Validation
254	     * does not catch). The names of all offending fields are collected so the caller receives a
255	     * 400 response whose {@code errors} array lists each one.
256	     */
257	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
258	        List<String> missingFields = new ArrayList<>();
259	        if (isBlank(ownerFieldsDto.getFirstName())) {
260	            missingFields.add("firstName");
261	        }
262	        if (isBlank(ownerFieldsDto.getLastName())) {
263	            missingFields.add("lastName");
264	        }
265	        if (isBlank(ownerFieldsDto.getAddress())) {
266	            missingFields.add("address");
267	        }
268	        if (isBlank(ownerFieldsDto.getCity())) {
269	            missingFields.add("city");
270	        }
271	        if (isBlank(ownerFieldsDto.getTelephone())) {
272	            missingFields.add("telephone");
273	        }
274	        if (!missingFields.isEmpty()) {
275	            throw new InvalidOwnerFieldsException(missingFields);
276	        }
277	    }
278	
279	    private static boolean isBlank(String value) {
280	        return value == null || value.trim().isEmpty();
281	    }
282	
283	    /**
284	     * Normalizes an owner's {@code address} on create and writes the canonical form back onto the
285	     * request so it is what gets validated, compared, stored and returned. The value is trimmed,
286	     * runs of internal whitespace are collapsed to a single space, the result is upper-cased and
287	     * common street-type abbreviations are expanded as whole tokens ({@code ST}->{@code STREET},
288	     * {@code RD}->{@code ROAD}, {@code AVE}->{@code AVENUE}). Running before the required-field check
289	     * means an address that is blank after normalization is rejected like a missing one.
290	     */
291	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
292	        ownerFieldsDto.setAddress(canonicalAddress(ownerFieldsDto.getAddress()));
293	    }
294	
295	    /**
296	     * Returns the canonical form of an address: trimmed, internal whitespace runs collapsed to a
297	     * single space, upper-cased, with common street-type abbreviations expanded as whole tokens. A
298	     * {@code null} value returns {@code null}. The transform is idempotent, so an already-canonical
299	     * address is returned unchanged, making it safe to apply to stored values during comparison.
300	     */
301	    private static String canonicalAddress(String address) {
302	        if (address == null) {
303	            return null;
304	        }
305	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
306	        if (collapsed.isEmpty()) {
307	            return "";
308	        }
309	        String[] tokens = collapsed.split(" ");
310	        StringBuilder sb = new StringBuilder(collapsed.length());
311	        for (int i = 0; i < tokens.length; i++) {
312	            if (i > 0) {
313	                sb.append(' ');
314	            }
315	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
316	        }
317	        return sb.toString();
318	    }
319	
320	    /**
321	     * Normalizes an owner's {@code telephone} on create into E.164 form. A leading {@code '+'} and
322	     * the country code that follows it are kept; otherwise the country code {@code '+61'} is assumed
323	     * and a single leading {@code '0'} is dropped from the national digits. Spaces, dashes and
324	     * brackets are stripped. The result must have 8 to 15 digits after the {@code '+'}. The E.164
325	     * string is written back onto the request so it is what gets stored and returned. Any value that
326	     * cannot form a valid E.164 number is rejected with a 400 response whose {@code errors} array
327	     * names {@code telephone}.
328	     */
329	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
330	        ownerFieldsDto.setTelephone(toE164(ownerFieldsDto.getTelephone()));
331	    }
332	
333	    /**
334	     * Converts a raw telephone value to E.164 form, or throws {@link InvalidOwnerFieldsException}
335	     * (400) naming {@code telephone} when it cannot form a valid number.
336	     */
337	    private static String toE164(String telephone) {
338	        if (telephone == null) {
339	            throw new InvalidOwnerFieldsException(List.of("telephone"));
340	        }
341	        boolean hasCountryCode = telephone.trim().startsWith("+");
342	        String digits = telephone.replaceAll("\\D", "");
343	        String national;
344	        if (hasCountryCode) {
345	            national = digits;
346	        } else {
347	            if (digits.startsWith("0")) {
348	                digits = digits.substring(1);
349	            }
350	            national = "61" + digits;
351	        }
352	        if (!national.matches("[0-9]{8,15}")) {
353	            throw new InvalidOwnerFieldsException(List.of("telephone"));
354	        }
355	        return "+" + national;
356	    }
357	
358	    /**
359	     * Rejects creating an owner whose E.164 telephone is already used by any other owner. The
360	     * incoming value has already been converted to its E.164 form by {@link #normalizeTelephone};
361	     * each existing owner's stored telephone is converted the same way before comparison so numbers
362	     * that only differ in formatting still collide. A match results in a 409 response naming
363	     * {@code telephone}.
364	     */
365	    private void rejectDuplicateTelephone(OwnerFieldsDto ownerFieldsDto) {
366	        String telephone = ownerFieldsDto.getTelephone();
367	        for (Owner existing : this.clinicService.findAllOwners()) {
368	            if (telephone.equals(normalizeExisting(existing.getTelephone()))) {
369	                throw new DuplicateOwnerTelephoneException(telephone);
370	            }
371	        }
372	    }
373	
374	    /**
375	     * Returns the E.164 form of an already-stored telephone for duplicate comparison, or {@code null}
376	     * when the stored value cannot form a valid E.164 number (so it never matches an incoming one).
377	     */
378	    private static String normalizeExisting(String telephone) {
379	        try {
380	            return toE164(telephone);
381	        } catch (InvalidOwnerFieldsException ex) {
382	            return null;
383	        }
384	    }
385	
386	    /**
387	     * Rejects creating an owner whose {@code lastName} and {@code address} already belong to another
388	     * owner. Both fields are compared case-insensitively and with runs of whitespace collapsed to a
389	     * single space, so values that differ only in letter case or spacing still collide. When the
390	     * request opts in with {@code sharesHousehold} set to {@code true} the check is skipped, allowing
391	     * household members to share a name and address. A match results in a 409 response naming
392	     * {@code lastName} and {@code address}.
393	     */
394	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
395	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
396	            return;
397	        }
398	        String lastName = normalizeForComparison(ownerFieldsDto.getLastName());
399	        String address = canonicalAddress(ownerFieldsDto.getAddress());
400	        for (Owner existing : this.clinicService.findAllOwners()) {
401	            if (lastName.equals(normalizeForComparison(existing.getLastName()))
402	                && address.equals(canonicalAddress(existing.getAddress()))) {
403	                throw new DuplicateOwnerHouseholdException(
404	                    ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
405	            }
406	        }
407	    }
408	
409	    /**
410	     * Rejects creating an owner in a city that has reached capacity: a city that already contains
411	     * {@value #MAX_OWNERS_PER_CITY} or more owners cannot take another one. Existing owners are
412	     * counted with a case-insensitive match on {@code city}, the same way {@link #assignCustomerCode}
413	     * groups a city. A city at or over the limit results in a 409 response naming {@code city}.
414	     */
415	    private void rejectCityAtCapacity(OwnerFieldsDto ownerFieldsDto) {
416	        String city = ownerFieldsDto.getCity();
417	        int count = 0;
418	        for (Owner existing : this.clinicService.findAllOwners()) {
419	            if (city.equalsIgnoreCase(existing.getCity())) {
420	                count++;
421	            }
422	        }
423	        if (count >= MAX_OWNERS_PER_CITY) {
424	            throw new OwnerCityAtCapacityException(city);
425	        }
426	    }
427	
428	    /**
429	     * Normalizes a value for case-insensitive, whitespace-insensitive comparison: leading and
430	     * trailing whitespace is trimmed, internal runs of whitespace are collapsed to a single space and
431	     * the result is lower-cased. A {@code null} value normalizes to the empty string.
432	     */
433	    private static String normalizeForComparison(String value) {
434	        if (value == null) {
435	            return "";
436	        }
437	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
438	    }
439	
440	    /**
441	     * Normalizes an owner's optional {@code email}. The field may be omitted entirely, but when a
442	     * value is present it must be a syntactically valid address; the trimmed value is lower-cased and
443	     * written back onto the request so that is what gets stored and returned. A present but invalid
444	     * address is rejected with a 400 response whose {@code errors} array names {@code email}.
445	     */
446	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
447	        String email = ownerFieldsDto.getEmail();
448	        if (email == null) {
449	            return;
450	        }
451	        String trimmed = email.trim();
452	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
453	            throw new InvalidOwnerFieldsException(List.of("email"));
454	        }
455	        ownerFieldsDto.setEmail(trimmed.toLowerCase(Locale.ROOT));
456	    }
457	
458	    /**
459	     * Defaults an owner's {@code registrationDate} on create. When the caller supplies no value,
460	     * it is set to the server's current date so every owner is persisted with a registration date;
461	     * a value provided in the request is kept as-is. The date is stored and returned in ISO
462	     * {@code YYYY-MM-DD} format.
463	     */
464	    private void defaultRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
465	        if (ownerFieldsDto.getRegistrationDate() == null) {
466	            ownerFieldsDto.setRegistrationDate(LocalDate.now());
467	        }
468	    }
469	
470	    /**
471	     * Assigns the owner's {@code customerCode} on create, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
472	     * where {@code CITY3} is the upper-cased first three letters of {@code city}, {@code LAST3} is the
473	     * upper-cased first three letters of {@code lastName} and {@code NNNN} is a per-city 4-digit
474	     * zero-padded sequence equal to one more than the number of owners already in that city
475	     * (e.g. {@code 'SYD-SMI-0007'}).
476	     */
477	    private void assignCustomerCode(Owner owner) {
478	        String city = owner.getCity();
479	        String lastName = owner.getLastName();
480	        String cityPrefix = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
481	        String lastPrefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
482	        int sequence = 1;
483	        for (Owner existing : this.clinicService.findAllOwners()) {
484	            if (city.equalsIgnoreCase(existing.getCity())) {
485	                sequence++;
486	            }
487	        }
488	        owner.setCustomerCode(String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence));
489	    }
490	
491	    /**
492	     * Assigns the owner's {@code membershipNumber} on create, formatted
493	     * {@code '<customerCode>-M<YY>'} where {@code YY} is the last two digits of the
494	     * {@code registrationDate} year (e.g. {@code 'SMI-0007-M26'}). Assigned after
495	     * {@link #assignCustomerCode} and once {@code registrationDate} has been defaulted, so both
496	     * inputs are present.
497	     */
498	    private void assignMembershipNumber(Owner owner) {
499	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
500	        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
501	    }
502	
503	    /**
504	     * Assigns the new owner's {@code namesakeCount} on create: the number of owners that already
505	     * exist sharing the same {@code firstName} and {@code lastName}, compared case-insensitively.
506	     * Computed before the new owner is persisted, so it counts only the pre-existing owners.
507	     */
508	    private void assignNamesakeCount(Owner owner) {
509	        String firstName = owner.getFirstName();
510	        String lastName = owner.getLastName();
511	        int count = 0;
512	        for (Owner existing : this.clinicService.findAllOwners()) {
513	            if (firstName.equalsIgnoreCase(existing.getFirstName())
514	                && lastName.equalsIgnoreCase(existing.getLastName())) {
515	                count++;
516	            }
517	        }
518	        owner.setNamesakeCount(count);
519	    }
520	
521	    /**
522	     * Assigns the new owner's {@code householdId} when the request opts in with
523	     * {@code sharesHousehold} set to {@code true} and at least one existing owner already shares the
524	     * same last name and address (compared case-insensitively with runs of whitespace collapsed, the
525	     * same way {@link #rejectDuplicateHousehold} matches). The household's members and the new owner
526	     * all end up carrying one stable shared identifier: if any existing member already has a
527	     * {@code householdId} it is reused, otherwise a new one is derived from the normalized last name
528	     * and address. Any existing member that is missing the identifier is updated so the whole
529	     * household stays consistent. When the flag is absent, or set but no matching owner exists, no
530	     * identifier is assigned.
531	     */
532	    private void assignHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto) {
533	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
534	            return;
535	        }
536	        String lastName = normalizeForComparison(owner.getLastName());
537	        String address = canonicalAddress(owner.getAddress());
538	        List<Owner> members = new ArrayList<>();
539	        for (Owner existing : this.clinicService.findAllOwners()) {
540	            if (lastName.equals(normalizeForComparison(existing.getLastName()))
541	                && address.equals(canonicalAddress(existing.getAddress()))) {
542	                members.add(existing);
543	            }
544	        }
545	        if (members.isEmpty()) {
546	            return;
547	        }
548	        String householdId = members.stream()
549	            .map(Owner::getHouseholdId)
550	            .filter(id -> id != null && !id.isBlank())
551	            .findFirst()
552	            .orElseGet(() -> newHouseholdId(lastName, address));
553	        owner.setHouseholdId(householdId);
554	        for (Owner member : members) {
555	            if (!householdId.equals(member.getHouseholdId())) {
556	                member.setHouseholdId(householdId);
557	                this.clinicService.saveOwner(member);
558	            }
559	        }
560	    }
561	
562	    /**
563	     * Derives a stable household identifier from the normalized last name and address: the first
564	     * twelve upper-case hex characters of the SHA-256 digest of {@code "<lastName>|<address>"}. Two
565	     * owners in the same household therefore derive the same value regardless of creation order.
566	     */
567	    private static String newHouseholdId(String normalizedLastName, String normalizedAddress) {
568	        try {
569	            byte[] digest = MessageDigest.getInstance("SHA-256")
570	                .digest((normalizedLastName + "|" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
571	            StringBuilder hex = new StringBuilder(digest.length * 2);
572	            for (byte b : digest) {
573	                hex.append(String.format("%02x", b));
574	            }
575	            return hex.substring(0, 12).toUpperCase(Locale.ROOT);
576	        } catch (NoSuchAlgorithmException ex) {
577	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
578	        }
579	    }
580	}
